mapper.update:
UPDATE ticket_source_issue_task
SET task_status='PROCESSING', last_attempt_time=#{now}, last_operation='PROCESS',
    version=version+1, update_time=#{now}
WHERE order_id=#{orderId}
  AND (
    task_status IN ('PENDING','WAIT_PROVIDER','RETRY_WAIT','PARTIAL','FAILED')
    OR (task_status='PROCESSING' AND last_attempt_time IS NOT NULL
        AND last_attempt_time <= #{processingCutoff})
  )

UPDATE electronic_ticket
SET ticket_status='ERROR', abnormal_reason=#{reason}, last_source_sync_time=#{now}, update_time=#{now}
WHERE order_id=#{orderId} AND ticket_status='GENERATING'
